import React from 'react';

import ThreeDotsVertical from '@pohodnik/icons/svg/Controls/ThreeDotsVertical';
import clsx from 'clsx';

import { ObstacleIcon } from '@apps/Obstacles/components/ObstacleIcon/ObstacleIcon';
import { formatDistance } from '@helpers/formatHelper';
import PohBadge, { BadgeVariant } from '@ui-kit/Badge/Badge';
import PohButton, { ButtonSize } from '@ui-kit/Button';
import PohDropdown from '@ui-kit/Dropdown';

import { getObstacleTitle } from '../../../../Obstacles/@helpers/obstacles.helper';
import { obstacleCategoryNameResource } from '../../../../Obstacles/@resources/obstacles.resource';
import { IRouteObject, RouteObjectType } from '../../../@types/routes.types';
import RouteObjectIcon from '../RouteObjectIcon';

interface IRoutesEditorListItemProps {
  routeObject: IRouteObject;
  menuActions?: Record<string, (e: React.MouseEvent) => void>;
}

const RoutesEditorListItem: React.FC<IRoutesEditorListItemProps> = ({
  routeObject,
  menuActions,
}) => {
  return (
    <div className="px-2 py-2 d-flex align-items-center">
      <RouteObjectIcon
        className="me-2"
        color={routeObject.color}
        type={routeObject.type}
        inDistance={routeObject.is_in_distance}
      />
      <span
        style={{ flexGrow: 1, opacity: routeObject.is_in_distance ? 1 : 0.5 }}
        title={[
          routeObject.name,
          routeObject.description,
          ['Создано:', routeObject.dateCreate, routeObject.author?.name].filter(Boolean).join('\t'),
          ['Изменено:', routeObject.dateUpdate, routeObject.updater?.name]
            .filter(Boolean)
            .join('\t'),
        ]
          .filter(Boolean)
          .join('\n')}
      >
        {routeObject.name}
      </span>
      {routeObject.type === RouteObjectType.Line && (
        <small>
          {routeObject.is_in_distance ? (
            <span className={clsx('text-success')}>{formatDistance(routeObject.distance)}</span>
          ) : (
            <s className={clsx('text-muted text-decoration-line-through')}>
              {formatDistance(routeObject.distance)}
            </s>
          )}
        </small>
      )}
      {/* {routeObject.type === RouteObjectType.Point && routeObject.coordinates[2] && <small>
        {routeObject.is_in_distance ? <span className={clsx("text-info")}>
          {formatAltitude(routeObject.coordinates[2])}
          </span>
        : <s className={clsx("text-muted text-decoration-line-through")}>
        {formatAltitude(routeObject.coordinates[2])}
        </s>}
      </small>} */}
      {routeObject.type === RouteObjectType.Point && routeObject.obstacle && (
        <PohBadge variant={BadgeVariant.Warning}>
          <small className={clsx('text-warn')} title={getObstacleTitle(routeObject.obstacle)}>
            <ObstacleIcon type={routeObject.obstacle.type} />
            &nbsp; {obstacleCategoryNameResource[routeObject.obstacle.category]}
          </small>
        </PohBadge>
      )}
      {menuActions && (
        <PohDropdown
          className="me-n2"
          onClick={(e) => e.stopPropagation()}
          menu={Object.entries(menuActions).map(([label, callback]) => {
            if (label.startsWith('---'))
              return (
                <li key={`bottom-level-menu-item-${label}`}>
                  <hr className="dropdown-divider" />
                </li>
              );
            return (
              <button
                key={`bottom-level-menu-item-${label}`}
                className="dropdown-item"
                onClick={callback}
                type="button"
              >
                {label}
              </button>
            );
          })}
        >
          <PohButton size={ButtonSize.Small} icon={true}>
            <ThreeDotsVertical />
          </PohButton>
        </PohDropdown>
      )}
    </div>
  );
};

export default RoutesEditorListItem;
